-- Resend transport and dated public rate support. No sends or accounts enabled.

-- Preserve every immutable SES/postal quote and the current postal policy guards.

PRAGMA defer_foreign_keys=ON;

DROP VIEW valid_live_delivery_quotes;

CREATE TABLE resend_migration_policy_backup AS SELECT * FROM trusted_delivery_costs;

DROP TABLE trusted_delivery_costs;

CREATE TABLE trusted_delivery_costs(id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), sender_id TEXT NOT NULL, channel TEXT NOT NULL CHECK(channel IN ('email','postal')), provider TEXT NOT NULL CHECK((channel='email' AND provider IN ('ses','resend')) OR (channel='postal' AND provider='pingen')), account_id TEXT NOT NULL CHECK(length(account_id) BETWEEN 1 AND 200), route_id TEXT NOT NULL CHECK(length(route_id) BETWEEN 1 AND 200), options_json TEXT NOT NULL CHECK(json_valid(options_json)), rate_json TEXT NOT NULL CHECK(json_valid(rate_json)), base_numerator INTEGER NOT NULL CHECK(typeof(base_numerator)='integer' AND base_numerator BETWEEN 0 AND 1000000000000000), byte_numerator INTEGER NOT NULL CHECK(typeof(byte_numerator)='integer' AND byte_numerator BETWEEN 0 AND 1000000000), rate_denominator INTEGER NOT NULL CHECK(typeof(rate_denominator)='integer' AND rate_denominator BETWEEN 1 AND 1000000000), currency TEXT NOT NULL CHECK(currency='EUR'), fiscal_basis TEXT NOT NULL CHECK(fiscal_basis='qualified_final_variable_cost'), quote_ttl_seconds INTEGER NOT NULL CHECK(quote_ttl_seconds BETWEEN 30 AND 900), source_reference TEXT NOT NULL CHECK(length(source_reference) BETWEEN 1 AND 500), source_sha256 TEXT NOT NULL CHECK(length(source_sha256)=64), valid_from TEXT NOT NULL, expires_at TEXT NOT NULL CHECK(expires_at>valid_from), status TEXT NOT NULL CHECK(status IN ('qualified','revoked')), created_at TEXT NOT NULL, pricing_basis TEXT NOT NULL DEFAULT 'qualified_final_variable_cost' CHECK(pricing_basis IN ('qualified_final_variable_cost','public_list_price_ex_tax')), UNIQUE(organization_id,id), FOREIGN KEY(organization_id,sender_id) REFERENCES senders(organization_id,id));

INSERT INTO trusted_delivery_costs SELECT * FROM resend_migration_policy_backup;

DROP TABLE resend_migration_policy_backup;

CREATE UNIQUE INDEX qualified_delivery_route ON trusted_delivery_costs(organization_id,sender_id,channel,provider,account_id,route_id,options_json) WHERE status='qualified';

CREATE TRIGGER immutable_delivery_cost BEFORE UPDATE ON trusted_delivery_costs WHEN NEW.pricing_basis IS NOT OLD.pricing_basis OR NEW.id IS NOT OLD.id OR NEW.organization_id IS NOT OLD.organization_id OR NEW.sender_id IS NOT OLD.sender_id OR NEW.channel IS NOT OLD.channel OR NEW.provider IS NOT OLD.provider OR NEW.account_id IS NOT OLD.account_id OR NEW.route_id IS NOT OLD.route_id OR NEW.options_json IS NOT OLD.options_json OR NEW.rate_json IS NOT OLD.rate_json OR NEW.base_numerator IS NOT OLD.base_numerator OR NEW.byte_numerator IS NOT OLD.byte_numerator OR NEW.rate_denominator IS NOT OLD.rate_denominator OR NEW.currency IS NOT OLD.currency OR NEW.fiscal_basis IS NOT OLD.fiscal_basis OR NEW.quote_ttl_seconds IS NOT OLD.quote_ttl_seconds OR NEW.source_reference IS NOT OLD.source_reference OR NEW.source_sha256 IS NOT OLD.source_sha256 OR NEW.valid_from IS NOT OLD.valid_from OR NEW.expires_at IS NOT OLD.expires_at OR NEW.created_at IS NOT OLD.created_at OR (OLD.status='revoked' AND NEW.status<>'revoked') BEGIN SELECT RAISE(ABORT,'immutable_delivery_cost'); END;

CREATE TRIGGER qualified_email_attachment_scope BEFORE INSERT ON trusted_delivery_costs WHEN NEW.channel='email' BEGIN SELECT RAISE(ABORT,'email_attachment_scope_invalid') WHERE json_extract(NEW.rate_json,'$.attachmentBasis')='included_pdf' AND NEW.provider<>'resend'; SELECT RAISE(ABORT,'email_attachment_scope_invalid') WHERE COALESCE(json_extract(NEW.rate_json,'$.attachmentBasis') IN ('no_attachments','raw_pdf_bytes','included_pdf'),0)=0 OR (json_extract(NEW.rate_json,'$.attachmentBasis') IN ('no_attachments','included_pdf') AND (NEW.byte_numerator<>0 OR json_type(NEW.rate_json,'$.usdMicrosPerGb') IS NOT NULL OR json_type(NEW.rate_json,'$.bytesPerGb') IS NOT NULL)); END;

CREATE TRIGGER qualified_public_email_price BEFORE INSERT ON trusted_delivery_costs BEGIN SELECT RAISE(ABORT,'public_email_price_invalid') WHERE (NEW.pricing_basis='public_list_price_ex_tax' AND COALESCE(((NEW.channel='email' AND NEW.provider='ses' AND NEW.options_json='{}' AND json_extract(NEW.rate_json,'$.attachmentBasis')='no_attachments' AND NEW.byte_numerator=0 AND json_extract(NEW.rate_json,'$.pricingBasis')='public_list_price_ex_tax' AND json_extract(NEW.rate_json,'$.plan')='Essentials' AND json_extract(NEW.rate_json,'$.tier')='0-10000000' AND json_extract(NEW.rate_json,'$.unit')='recipient' AND json_extract(NEW.rate_json,'$.currency')='USD' AND json_extract(NEW.rate_json,'$.tariffSource')='https://aws.amazon.com/ses/pricing/' AND json_extract(NEW.rate_json,'$.fxBasis')='commercial_fixed_reference' AND json_extract(NEW.rate_json,'$.fxSource')='https://www.ecb.europa.eu/stats/eurofxref/eurofxref-daily.xml' AND json_type(NEW.rate_json,'$.usdMicrosPerMessage')='integer' AND json_extract(NEW.rate_json,'$.usdMicrosPerMessage')>0 AND json_type(NEW.rate_json,'$.tariffDate')='text' AND json_extract(NEW.rate_json,'$.tariffDate')=date(json_extract(NEW.rate_json,'$.tariffDate')) AND length(json_extract(NEW.rate_json,'$.tariffDate'))=10 AND json_extract(NEW.rate_json,'$.tariffDate')<=substr(NEW.valid_from,1,10) AND json_type(NEW.rate_json,'$.fxDate')='text' AND json_extract(NEW.rate_json,'$.fxDate')=date(json_extract(NEW.rate_json,'$.fxDate')) AND length(json_extract(NEW.rate_json,'$.fxDate'))=10 AND json_extract(NEW.rate_json,'$.fxDate')<=substr(NEW.valid_from,1,10)) OR (NEW.channel='email' AND NEW.provider='resend' AND NEW.options_json='{}' AND json_extract(NEW.rate_json,'$.attachmentBasis')='included_pdf' AND NEW.byte_numerator=0 AND json_extract(NEW.rate_json,'$.pricingBasis')='public_list_price_ex_tax' AND json_extract(NEW.rate_json,'$.plan')='Pro' AND json_extract(NEW.rate_json,'$.tier')='additional_emails' AND json_extract(NEW.rate_json,'$.unit')='recipient' AND json_extract(NEW.rate_json,'$.currency')='USD' AND json_extract(NEW.rate_json,'$.tariffSource')='https://resend.com/pricing' AND json_extract(NEW.rate_json,'$.fxBasis')='commercial_fixed_reference' AND json_extract(NEW.rate_json,'$.fxSource')='https://www.ecb.europa.eu/stats/eurofxref/eurofxref-daily.xml' AND json_type(NEW.rate_json,'$.usdMicrosPerMessage')='integer' AND json_extract(NEW.rate_json,'$.usdMicrosPerMessage')=900 AND json_type(NEW.rate_json,'$.tariffDate')='text' AND json_extract(NEW.rate_json,'$.tariffDate')=date(json_extract(NEW.rate_json,'$.tariffDate')) AND length(json_extract(NEW.rate_json,'$.tariffDate'))=10 AND json_extract(NEW.rate_json,'$.tariffDate')<=substr(NEW.valid_from,1,10) AND json_type(NEW.rate_json,'$.fxDate')='text' AND json_extract(NEW.rate_json,'$.fxDate')=date(json_extract(NEW.rate_json,'$.fxDate')) AND length(json_extract(NEW.rate_json,'$.fxDate'))=10 AND json_extract(NEW.rate_json,'$.fxDate')<=substr(NEW.valid_from,1,10)) OR (NEW.channel='postal' AND NEW.provider='pingen' AND NEW.account_id=NEW.route_id AND NEW.base_numerator=0 AND NEW.byte_numerator=0 AND NEW.rate_denominator=1 AND json_type(NEW.rate_json)='object' AND (SELECT count(*) FROM json_each(NEW.rate_json))=8 AND json_extract(NEW.rate_json,'$.pricingBasis')='public_list_price_ex_tax' AND json_extract(NEW.rate_json,'$.method')='pingen_price_calculator' AND json_extract(NEW.rate_json,'$.currency')='EUR' AND json_extract(NEW.rate_json,'$.unit')='letter' AND json_extract(NEW.rate_json,'$.tariffSource')='https://api.pingen.com/documentation/swagger-docs' AND json_extract(NEW.rate_json,'$.taxBasis')='shipping_price_excluding_vat' AND json_extract(NEW.rate_json,'$.taxSource')='https://help.pingen.com/en/credits-and-billing/introduction-balance-and-credits' AND json_type(NEW.rate_json,'$.tariffDate')='text' AND length(json_extract(NEW.rate_json,'$.tariffDate'))=10 AND json_extract(NEW.rate_json,'$.tariffDate')=date(json_extract(NEW.rate_json,'$.tariffDate'),'+0 days') AND json_extract(NEW.rate_json,'$.tariffDate')<=substr(NEW.valid_from,1,10) AND json_extract(NEW.options_json,'$.addressPosition') IN ('left','right') AND json_extract(NEW.options_json,'$.deliveryProduct') IN ('cheap','fast') AND json_extract(NEW.options_json,'$.printMode') IN ('simplex','duplex') AND json_extract(NEW.options_json,'$.printSpectrum') IN ('grayscale','color') AND NEW.options_json=json_object('addressPosition',json_extract(NEW.options_json,'$.addressPosition'),'deliveryProduct',json_extract(NEW.options_json,'$.deliveryProduct'),'printMode',json_extract(NEW.options_json,'$.printMode'),'printSpectrum',json_extract(NEW.options_json,'$.printSpectrum')))),0)=0) OR (NEW.pricing_basis='qualified_final_variable_cost' AND json_type(NEW.rate_json,'$.pricingBasis') IS NOT NULL); END;

CREATE VIEW valid_live_delivery_quotes AS SELECT q.*,p.valid_from AS policy_valid_from,p.expires_at AS policy_expires_at FROM live_delivery_quotes q JOIN dispatches d ON d.organization_id=q.organization_id AND d.id=q.dispatch_id JOIN trusted_delivery_costs p ON p.organization_id=q.organization_id AND p.id=q.policy_id JOIN senders s ON s.organization_id=d.organization_id AND s.id=d.sender_id LEFT JOIN documents doc ON doc.organization_id=d.organization_id AND doc.id=d.document_id WHERE (d.provider IS NULL OR d.provider=q.provider) AND d.mode='production' AND d.channel=q.channel AND d.quote_fingerprint=q.fingerprint AND d.fingerprint=q.dispatch_fingerprint AND p.status='qualified' AND p.sender_id=d.sender_id AND p.channel=d.channel AND p.provider=q.provider AND p.account_id=q.account_id AND p.route_id=q.route_id AND s.status='verified' AND s.mode='production' AND s.channel=d.channel AND s.address=d.sender_address AND (d.document_id IS NULL OR (doc.status='ready' AND doc.sha256=json_extract(q.input_json,'$.documentSha256'))) AND q.attachment_bytes=COALESCE(doc.size,0) AND q.amount_minor=d.estimated_minor AND q.ceiling_minor=d.ceiling_minor AND q.currency=d.currency AND q.source_reference=p.source_reference AND q.source_sha256=p.source_sha256 AND q.fiscal_basis=p.pricing_basis AND (p.pricing_basis='qualified_final_variable_cost' OR (json_extract(q.input_json,'$.pricingBasis')='public_list_price_ex_tax' AND json_extract(q.input_json,'$.fx.numerator')=json_extract(p.rate_json,'$.eurPerUsdNumerator') AND json_extract(q.input_json,'$.fx.denominator')=json_extract(p.rate_json,'$.eurPerUsdDenominator') AND json_extract(q.input_json,'$.fx.date')=json_extract(p.rate_json,'$.fxDate') AND json_extract(q.input_json,'$.fx.source')=json_extract(p.rate_json,'$.fxSource') AND p.channel='email') OR (p.pricing_basis='public_list_price_ex_tax' AND p.channel='postal' AND p.provider='pingen' AND p.account_id=p.route_id AND p.base_numerator=0 AND p.byte_numerator=0 AND p.rate_denominator=1 AND json_type(p.rate_json)='object' AND (SELECT count(*) FROM json_each(p.rate_json))=8 AND json_extract(p.rate_json,'$.pricingBasis')='public_list_price_ex_tax' AND json_extract(p.rate_json,'$.method')='pingen_price_calculator' AND json_extract(p.rate_json,'$.currency')='EUR' AND json_extract(p.rate_json,'$.unit')='letter' AND json_extract(p.rate_json,'$.tariffSource')='https://api.pingen.com/documentation/swagger-docs' AND json_extract(p.rate_json,'$.taxBasis')='shipping_price_excluding_vat' AND json_extract(p.rate_json,'$.taxSource')='https://help.pingen.com/en/credits-and-billing/introduction-balance-and-credits' AND json_type(p.rate_json,'$.tariffDate')='text' AND length(json_extract(p.rate_json,'$.tariffDate'))=10 AND json_extract(p.rate_json,'$.tariffDate')=date(json_extract(p.rate_json,'$.tariffDate'),'+0 days') AND json_extract(p.rate_json,'$.tariffDate')<=substr(p.valid_from,1,10) AND json_extract(p.options_json,'$.addressPosition') IN ('left','right') AND json_extract(p.options_json,'$.deliveryProduct') IN ('cheap','fast') AND json_extract(p.options_json,'$.printMode') IN ('simplex','duplex') AND json_extract(p.options_json,'$.printSpectrum') IN ('grayscale','color') AND p.options_json=json_object('addressPosition',json_extract(p.options_json,'$.addressPosition'),'deliveryProduct',json_extract(p.options_json,'$.deliveryProduct'),'printMode',json_extract(p.options_json,'$.printMode'),'printSpectrum',json_extract(p.options_json,'$.printSpectrum')) AND json_extract(q.input_json,'$.pricingBasis')='public_list_price_ex_tax' AND json_type(q.input_json,'$.fx') IS NULL)) AND q.expires_at<=p.expires_at AND q.expires_at<=strftime('%Y-%m-%dT%H:%M:%fZ',q.created_at,'+'||p.quote_ttl_seconds||' seconds') AND json_extract(q.input_json,'$.channel') IS d.channel AND json_extract(q.input_json,'$.recipient') IS d.recipient_json AND json_extract(q.input_json,'$.documentId') IS d.document_id AND json_extract(q.input_json,'$.senderId') IS d.sender_id AND json_extract(q.input_json,'$.senderAddress') IS d.sender_address AND json_extract(q.input_json,'$.subject') IS d.subject AND json_extract(q.input_json,'$.html') IS d.html AND json_extract(q.input_json,'$.text') IS d.text AND json_extract(q.input_json,'$.options') IS d.options_json AND json_extract(q.input_json,'$.campaignId') IS d.campaign_id AND json_extract(q.input_json,'$.estimatedMinor') IS d.estimated_minor AND json_extract(q.input_json,'$.ceilingMinor') IS d.ceiling_minor AND json_extract(q.input_json,'$.currency') IS d.currency AND json_extract(q.input_json,'$.mode') IS d.mode AND ((d.channel='email' AND (json_extract(p.rate_json,'$.attachmentBasis')='raw_pdf_bytes' OR (p.provider='resend' AND json_extract(p.rate_json,'$.attachmentBasis')='included_pdf' AND p.byte_numerator=0) OR (json_extract(p.rate_json,'$.attachmentBasis')='no_attachments' AND d.document_id IS NULL AND q.attachment_bytes=0 AND p.byte_numerator=0 AND json_type(p.rate_json,'$.usdMicrosPerGb') IS NULL AND json_type(p.rate_json,'$.bytesPerGb') IS NULL)) AND (p.options_json=d.options_json OR (p.provider='resend' AND p.options_json='{}')) AND q.provider_draft_id IS NULL AND q.prepared_letter_id IS NULL AND q.supplier_numerator=CAST(p.base_numerator+p.byte_numerator*q.attachment_bytes AS TEXT) AND q.supplier_denominator=CAST(p.rate_denominator AS TEXT) AND q.supplier_nanoeur=(p.base_numerator+p.byte_numerator*q.attachment_bytes+p.rate_denominator-1)/p.rate_denominator AND q.evidence_sha256=p.source_sha256) OR (d.channel='postal' AND doc.id IS NOT NULL AND q.supplier_nanoeur%10000000=0 AND q.supplier_numerator=CAST(q.supplier_nanoeur AS TEXT) AND q.supplier_denominator='1' AND EXISTS(SELECT 1 FROM provider_drafts pd WHERE pd.organization_id=d.organization_id AND pd.id=q.provider_draft_id AND pd.provider='pingen' AND pd.status='prepared' AND pd.provider_id=q.prepared_letter_id AND pd.document_id=doc.id AND pd.document_sha256=doc.sha256 AND pd.sender_id=s.id AND pd.sender_address=s.address AND pd.recipient_json=d.recipient_json AND pd.options_json=p.options_json AND pd.ceiling_minor=d.ceiling_minor AND pd.currency=d.currency AND (pd.claimed_dispatch_id IS NULL OR pd.claimed_dispatch_id=d.id) AND json_extract(d.options_json,'$.providerDraftId')=pd.id AND json_extract(d.options_json,'$.preparedLetterId')=pd.provider_id AND json_extract(d.options_json,'$.expectedAddress')=pd.expected_address AND json_extract(d.options_json,'$.addressPosition')=json_extract(pd.options_json,'$.addressPosition') AND json_extract(d.options_json,'$.deliveryProduct')=json_extract(pd.options_json,'$.deliveryProduct') AND json_extract(d.options_json,'$.printMode')=json_extract(pd.options_json,'$.printMode') AND json_extract(d.options_json,'$.printSpectrum')=json_extract(pd.options_json,'$.printSpectrum'))));

DROP TRIGGER preflight_live_delivery;

CREATE TRIGGER preflight_live_delivery BEFORE UPDATE OF status ON dispatches WHEN OLD.status='queued' AND NEW.status='submitting' AND NEW.mode='production' AND NEW.channel IN ('email','postal') BEGIN SELECT RAISE(ABORT,'live_quote_invalid') WHERE NOT EXISTS(SELECT 1 FROM valid_live_delivery_quotes WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.id AND provider=NEW.provider AND created_at<=NEW.updated_at AND expires_at>NEW.updated_at AND policy_valid_from<=NEW.updated_at AND policy_expires_at>NEW.updated_at); END;

CREATE TABLE resend_send_limit_policies(account_id TEXT PRIMARY KEY CHECK(length(account_id) BETWEEN 1 AND 200), max_recipients_24h INTEGER NOT NULL CHECK(typeof(max_recipients_24h)='integer' AND max_recipients_24h BETWEEN 1 AND 1000000), max_recipients_month INTEGER NOT NULL DEFAULT 2700 CHECK(typeof(max_recipients_month)='integer' AND max_recipients_month BETWEEN 1 AND 10000000), min_interval_ms INTEGER NOT NULL CHECK(typeof(min_interval_ms)='integer' AND min_interval_ms BETWEEN 200 AND 86400000), qualified_at_ms INTEGER NOT NULL, expires_at_ms INTEGER NOT NULL CHECK(expires_at_ms>qualified_at_ms), source_sha256 TEXT NOT NULL CHECK(length(source_sha256)=64), status TEXT NOT NULL CHECK(status IN ('qualified','revoked')));
CREATE TABLE resend_send_reservations(attempt_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, dispatch_id TEXT NOT NULL, account_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('reserved','accepted','unknown','rejected')), reserved_at_ms INTEGER NOT NULL, completed_at_ms INTEGER, FOREIGN KEY(organization_id,dispatch_id,attempt_id) REFERENCES attempts(organization_id,dispatch_id,id));
CREATE INDEX resend_recent_sends ON resend_send_reservations(account_id,status,completed_at_ms);
CREATE TRIGGER resend_attempt_outcome AFTER UPDATE OF status ON attempts WHEN NEW.provider='resend' AND NEW.status IN ('accepted','unknown','rejected') BEGIN UPDATE resend_send_reservations SET status=NEW.status,completed_at_ms=MAX(reserved_at_ms,CAST((julianday(NEW.updated_at)-2440587.5)*86400000 AS INTEGER)) WHERE attempt_id=NEW.id AND organization_id=NEW.organization_id AND dispatch_id=NEW.dispatch_id AND status IN ('reserved','unknown'); END;
CREATE TRIGGER immutable_resend_send_reservation BEFORE UPDATE ON resend_send_reservations WHEN NEW.attempt_id<>OLD.attempt_id OR NEW.organization_id<>OLD.organization_id OR NEW.dispatch_id<>OLD.dispatch_id OR NEW.account_id<>OLD.account_id OR NEW.reserved_at_ms<>OLD.reserved_at_ms OR OLD.status IN ('accepted','rejected') OR NEW.status='reserved' BEGIN SELECT RAISE(ABORT,'immutable_resend_send_reservation'); END;
CREATE TRIGGER resend_dispatch_acceptance AFTER UPDATE OF status,provider_id ON dispatches WHEN NEW.channel='email' AND NEW.mode='production' AND NEW.provider='resend' AND length(NEW.provider_id)>0 AND NEW.status IN ('accepted','delivered','failed','bounced','complained') BEGIN UPDATE resend_send_reservations SET status='accepted',completed_at_ms=MAX(reserved_at_ms,CAST((julianday(NEW.updated_at)-2440587.5)*86400000 AS INTEGER)) WHERE attempt_id=NEW.active_attempt_id AND organization_id=NEW.organization_id AND dispatch_id=NEW.id AND status IN ('reserved','unknown'); END;
-- Preserve existing suppression reasons while representing provider suppression truthfully.
CREATE TABLE resend_migration_suppression_backup AS SELECT * FROM suppressions;
DROP TABLE suppressions;
CREATE TABLE suppressions(organization_id TEXT NOT NULL REFERENCES organizations(id), email TEXT NOT NULL, reason TEXT NOT NULL CHECK(reason IN ('hard_bounce','complaint','unsubscribe','provider_suppression')), created_at TEXT NOT NULL, PRIMARY KEY(organization_id,email));
INSERT INTO suppressions SELECT * FROM resend_migration_suppression_backup;
DROP TABLE resend_migration_suppression_backup;
PRAGMA defer_foreign_keys=OFF;
